-- ExpenseMate PostgreSQL schema, version 001.
-- Equivalent of the Assignment 01 SQLite schema (app/backend/db.py,
-- Database.init_schema) translated to PostgreSQL types.
--
--   SQLite                              PostgreSQL
--   INTEGER PRIMARY KEY AUTOINCREMENT   INTEGER GENERATED BY DEFAULT AS IDENTITY
--   REAL   (money)                      NUMERIC(14,2)  (exact decimal)
--   TEXT   (dates)                      DATE / TIMESTAMP
--   datetime('now')                     now()
--
-- "BY DEFAULT" identity columns allow the migration script to insert the
-- original ids so every foreign key keeps pointing at the same row.

CREATE TABLE IF NOT EXISTS users (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      TEXT        NOT NULL UNIQUE,
    password      TEXT        NOT NULL,
    base_currency VARCHAR(3)  NOT NULL DEFAULT 'USD',
    created_at    TIMESTAMP   NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS categories (
    id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL CHECK (kind IN ('income', 'expense'))
);

CREATE TABLE IF NOT EXISTS transactions (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     INTEGER       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    date        DATE          NOT NULL,
    description TEXT          NOT NULL,
    amount      NUMERIC(14,2) NOT NULL CHECK (amount >= 0),
    type        TEXT          NOT NULL CHECK (type IN ('income', 'expense')),
    category_id INTEGER       REFERENCES categories(id),
    currency    VARCHAR(3)    NOT NULL DEFAULT 'USD',
    created_at  TIMESTAMP     NOT NULL DEFAULT now()
);

-- Every transaction list/summary filters by user and month.
CREATE INDEX IF NOT EXISTS idx_transactions_user_date
    ON transactions (user_id, date);

CREATE TABLE IF NOT EXISTS budgets (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          INTEGER       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    category_id      INTEGER       NOT NULL REFERENCES categories(id),
    month            CHAR(7)       NOT NULL CHECK (month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
    amount           NUMERIC(14,2) NOT NULL CHECK (amount >= 0),
    -- LEGACY (Assignment 01): a running balance that was mutated on every
    -- expense insert/delete. Kept only so migrated data is preserved; the
    -- application now CALCULATES the remaining amount from the transactions
    -- (see services/budget_calculator.py) and stores NULL here.
    remaining_amount NUMERIC(14,2),
    currency         VARCHAR(3)    NOT NULL DEFAULT 'USD',
    UNIQUE (user_id, category_id, month)
);

CREATE TABLE IF NOT EXISTS settings (
    key   TEXT PRIMARY KEY,
    value TEXT
);
